/* 类型队列核心拥有固定值槽；公开结构只用于栈分配，不允许直接修改字段。 */
typedef struct xtypedqueuecore {
	const xrttype* ItemType;
	ptr Allocation;
	bytes Values;
	size_t Stride;
	size_t Capacity;
	size_t ValueBytes;
	xatomic32 State;
	xatomic32 Active;
} xtypedqueuecore;



/* 对象负载中的类型队列通过元数据声明固定容量。 */
typedef struct xtypedqueuemeta {
	size_t Capacity;
} xtypedqueuemeta;



