typedef enum xtypedqueueerror {
	XTYPED_QUEUE_ERROR_ARGUMENT = 1,
	XTYPED_QUEUE_ERROR_TYPE,
	XTYPED_QUEUE_ERROR_LAYOUT,
	XTYPED_QUEUE_ERROR_OPERATION,
	XTYPED_QUEUE_ERROR_STATE
} xtypedqueueerror;

